import math

def is_pretty(m, n, alpha, k):
    if m <= 0 or n <= 0:
        return False
    # Use a small epsilon to handle potential floating point issues
    # although for irrational alpha, n*alpha will never be an integer.
    val = m * math.ceil(n * alpha) - n * math.floor(m * alpha)
    return abs(val - k) < 1e-9

def is_cool(m, n, alpha, k):
    if not is_pretty(m, n, alpha, k):
        return False
    if m > n and is_pretty(m - n, n, alpha, k):
        return False
    if n > m and is_pretty(m, n - m, alpha, k):
        return False
    return True

