import math

def is_pretty(m, n, alpha, k):
    if m <= 0 or n <= 0:
        return False
    # Use decimal or just be careful with floats
    # Since alpha is irrational, n*alpha is never an integer.
    # So ceil(n*alpha) = floor(n*alpha) + 1
    # The condition is m(floor(n*alpha) + 1) - n*floor(m*alpha) = k
    return m * math.ceil(n * alpha) - n * math.floor(m * alpha) == k

def is_cool(m, n, alpha, k):
    if not is_pretty(m, n, alpha, k):
        return False
    if m > n:
        if is_pretty(m - n, n, alpha, k):
            return False
    if n > m:
        if is_pretty(m, n - m, alpha, k):
            return False
    return True

def count_cool_pairs(k, alpha, max_m, max_n):
    count = 0
    for m in range(1, max_m + 1):
        for n in range(1, max_n + 1):
            if is_cool(m, n, alpha, k):
                count += 1
    return count

